import com.google.gson.stream.*;
import java.io.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;
import org.apache.commons.compress.archivers.zip.*;
import org.json.*;
import org.jsoup.nodes.Element;
import org.jsoup.parser.*;
import local.snapexplorer.mobile.JsonRecords;

/** User-run, network-blocked inventory. No values, names, paths or IDs enter reports. */
public final class OfflineInspector {
 static final String MARKER="Snap Export Inspector reports v1";
 static final Set<String> REF_KEYS=new HashSet<>(Arrays.asList("mediaid","mediaids","mediapath","mediareferences","mediareference","stickerid","stickerids","stickerpath","customstickerid","customstickerids","customstickerpath","bitmojiid","bitmojipath","downloadlink","downloadurl","mediaurl","stickerurl","url","uri","src","href","filepath","filename"));
 static final Set<String> MEDIA_EXT=new HashSet<>(Arrays.asList("jpg","jpeg","png","gif","webp","heic","heif","avif","bmp","mp4","mov","m4v","webm","mkv","mp3","m4a","aac","ogg","opus","wav","flac","svg","tgs","lottie","pdf","txt","csv","vcf","ics","docx","xlsx"));
 static final java.util.regex.Pattern ID=java.util.regex.Pattern.compile("(?i)[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|[0-9a-f]{32,64}");
 final Map<String,Set<Integer>> aliases=new HashMap<>();
 final Map<String,Long> assets=new TreeMap<>(),datasets=new TreeMap<>(),formats=new TreeMap<>(),refStats=new TreeMap<>();
 long files,bytes,jsonFiles,htmlFiles,records,chatRecords,htmlMessages,metadataIssues,nestedArchives,unknownJsonFiles,unrecognizedAssetFormats;
 int assetId;final List<Path> inputs=new ArrayList<>();
 static String key(String text){return text.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
 static void bump(Map<String,Long> map,String name){map.put(name,map.getOrDefault(name,0L)+1);}
 static String leaf(String path){String value=path.replace('\\','/');return value.substring(value.lastIndexOf('/')+1);}
 static String ext(String path){String name=leaf(path);int dot=name.lastIndexOf('.');return dot<0?"":name.substring(dot+1).toLowerCase(Locale.ROOT);}
 static String category(String name){String n=leaf(name).toLowerCase(Locale.ROOT);if(n.equals("chat_history.json"))return "Chats";if(n.contains("sticker"))return "Stickers and custom stickers";if(n.contains("bitmoji")||n.contains("avatar"))return "Bitmoji and avatars";if(n.contains("memories"))return "Memories";if(n.contains("friend")||n.contains("contact"))return "Friends and contacts";if(n.contains("location")||n.contains("map"))return "Locations";if(n.contains("snap")||n.contains("stor")||n.contains("spotlight"))return "Snaps stories and Spotlight";if(n.contains("account")||n.contains("profile")||n.contains("login")||n.contains("device"))return "Account profile and devices";if(n.contains("search"))return "Search history";if(n.contains("purchase")||n.contains("shop"))return "Purchases";return "Other JSON metadata";}
 static boolean safe(String path){if(path.startsWith("/")||path.contains("\\")||path.indexOf('\0')>=0)return false;for(String p:path.split("/"))if(p.equals(".."))return false;return true;}
 static String assetCategory(String path){String p=path.toLowerCase(Locale.ROOT),e=ext(p);if(Arrays.asList("pdf","txt","csv","vcf","ics","docx","xlsx").contains(e))return "Documents and other attachments";if(p.contains("custom_sticker")||p.contains("customsticker"))return "Custom sticker files";if(p.contains("sticker"))return "Sticker files";if(p.contains("bitmoji")||p.contains("avatar"))return "Bitmoji and avatar files";if(p.contains("overlay"))return "Overlay files";if(Arrays.asList("mp4","mov","m4v","webm","mkv").contains(e))return "Videos";if(Arrays.asList("mp3","m4a","aac","ogg","opus","wav","flac").contains(e))return "Audio and voice files";if(Arrays.asList("gif","webp").contains(e))return "Images with possible animation";if(Arrays.asList("svg","tgs","lottie","pdf","txt","csv","vcf","ics","docx","xlsx").contains(e))return "Vector or animation assets";return "Photos and other images";}
 interface Input {InputStream open()throws Exception;}
 interface EntrySink {void accept(String name,long size,Input input)throws Exception;}
 void entries(Path path,EntrySink sink,int depth)throws Exception{
  if(depth>2)throw new IOException("Archive nesting limit");
  if(Files.isSymbolicLink(path))return;
  if(Files.isDirectory(path)){try(java.util.stream.Stream<Path> stream=Files.walk(path)){Iterator<Path> it=stream.iterator();while(it.hasNext()){Path file=it.next();if(Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)){if(ext(file.toString()).equals("zip"))entries(file,sink,depth);else sink.accept(path.relativize(file).toString().replace(File.separatorChar,'/'),Files.size(file),()->Files.newInputStream(file));}}}return;}
  if(!ext(path.toString()).equals("zip"))throw new IOException("Choose ZIP parts or an export folder");
  try(ZipFile zip=new ZipFile(path.toFile())){Enumeration<ZipArchiveEntry> all=zip.getEntries();int count=0;while(all.hasMoreElements()){ZipArchiveEntry e=all.nextElement();if(++count>200000)throw new IOException("Archive entry limit");if(e.isDirectory()||!safe(e.getName()))continue;if(ext(e.getName()).equals("zip")&&!e.getName().toLowerCase(Locale.ROOT).contains("chat_media/")){try(InputStream in=zip.getInputStream(e)){nested(in,sink,depth+1);}}else sink.accept(e.getName(),e.getSize(),()->zip.getInputStream(e));}}
 }
 void nested(InputStream in,EntrySink sink,int depth)throws Exception{if(depth>2)throw new IOException("Archive nesting limit");nestedArchives++;try(ZipArchiveInputStream zip=new ZipArchiveInputStream(new NonClosing(in))){ZipArchiveEntry e;int count=0;while((e=zip.getNextZipEntry())!=null){if(++count>200000)throw new IOException("Nested entry limit");if(e.isDirectory()||!safe(e.getName()))continue;if(ext(e.getName()).equals("zip")&&!e.getName().toLowerCase(Locale.ROOT).contains("chat_media/"))nested(zip,sink,depth+1);else sink.accept(e.getName(),e.getSize(),()->new NonClosing(zip));}}}
 static final class NonClosing extends FilterInputStream {NonClosing(InputStream in){super(in);}@Override public void close(){}}
 void alias(String value,int id){if(value.isEmpty())return;aliases.computeIfAbsent(value.toLowerCase(Locale.ROOT),k->new HashSet<>()).add(id);}
 void index(String name,long size,Input input){files++;bytes+=Math.max(0,size);String extension=ext(name);bump(formats,MEDIA_EXT.contains(extension)?extension:extension.equals("json")?"json":extension.equals("html")?"html":"other");boolean assetFolder=name.toLowerCase(Locale.ROOT).matches("(?:.*/)?(?:chat_media|media|memories|custom[_ -]?stickers?|stickers?|bitmojis?|avatars?)/.*");if(!MEDIA_EXT.contains(extension)&&!(assetFolder&&!Arrays.asList("json","html","css","js","txt","woff","woff2","ttf").contains(extension)))return;if(!MEDIA_EXT.contains(extension))unrecognizedAssetFormats++;int id=++assetId;bump(assets,assetCategory(name));alias(name,id);String base=leaf(name);alias(base,id);int dot=base.lastIndexOf('.');if(dot>0)alias(base.substring(0,dot),id);java.util.regex.Matcher ids=ID.matcher(base);while(ids.find())alias(ids.group(),id);for(String token:base.split("[^A-Za-z0-9]+"))if(token.length()>=8)alias(token,id);}
 Set<Integer> match(String raw){Set<Integer> matches=new HashSet<>();String value=raw.trim();String path=value;try{URI uri=URI.create(value.replace(" ","%20"));if(uri.getPath()!=null&&!uri.getPath().isEmpty())path=uri.getPath();}catch(Exception ignored){}for(String candidate:Arrays.asList(value,path,leaf(path))){Set<Integer> found=aliases.get(candidate.toLowerCase(Locale.ROOT));if(found!=null)matches.addAll(found);}java.util.regex.Matcher ids=ID.matcher(value);while(ids.find()){Set<Integer> found=aliases.get(ids.group().toLowerCase(Locale.ROOT));if(found!=null)matches.addAll(found);}return matches;}
 void ref(String raw,boolean sticker,boolean chat){String value=raw.trim();if(value.isEmpty()||value.startsWith("data:"))return;if(value.matches("(?i)[0-9a-f-]{8,}(?:\\s*,\\s*[0-9a-f-]{8,})+")){for(String part:value.split(","))ref(part,sticker,chat);return;}if(value.startsWith("[")){try{JSONArray array=new JSONArray(value);for(int i=0;i<array.length();i++)if(array.opt(i) instanceof String)ref(array.getString(i),sticker,chat);return;}catch(Exception ignored){return;}}
  bump(refStats,"References observed");if(sticker)bump(refStats,"Sticker references");if(chat)bump(refStats,"Chat-record references");boolean remote=value.toLowerCase(Locale.ROOT).matches("^https?://.*");if(remote)bump(refStats,"Download or remote references");Set<Integer> found=match(value);if(found.size()==1)bump(refStats,"References with one local candidate");else if(found.size()>1)bump(refStats,"References with ambiguous local candidates");else bump(refStats,remote?"Remote references without a local candidate":"IDs or paths without a local candidate");}
 void references(Object object,boolean sticker,boolean chat,int depth){if(depth>96)return;if(object instanceof JSONObject){JSONObject row=(JSONObject)object;Iterator<String> fields=row.keys();while(fields.hasNext()){String name=fields.next(),field=key(name);Object value=row.opt(name);boolean isSticker=sticker||field.contains("sticker")||field.contains("bitmoji");if(REF_KEYS.contains(field)||isSticker&&(field.equals("id")||field.endsWith("url")||field.endsWith("path"))||(field.contains("media")||field.contains("sticker")||field.contains("bitmoji"))&&(field.endsWith("url")||field.endsWith("id")||field.endsWith("ids")||field.endsWith("path"))){if(value instanceof String)ref((String)value,isSticker,chat);else if(value instanceof Number&&value.toString().matches("[0-9]{1,128}"))ref(value.toString(),isSticker,chat);else if(value instanceof JSONArray){JSONArray list=(JSONArray)value;for(int i=0;i<list.length();i++){Object item=list.opt(i);if(item instanceof String)ref((String)item,isSticker,chat);else if(item instanceof Number&&item.toString().matches("[0-9]{1,128}"))ref(item.toString(),isSticker,chat);else references(item,isSticker,chat,depth+1);}}else references(value,isSticker,chat,depth+1);}else if(value instanceof JSONObject||value instanceof JSONArray)references(value,isSticker,chat,depth+1);}}else if(object instanceof JSONArray){JSONArray list=(JSONArray)object;for(int i=0;i<list.length();i++)references(list.opt(i),sticker,chat,depth+1);}}
 void inspect(String name,long size,Input input){String extension=ext(name);if(extension.equals("json")){jsonFiles++;String dataset=category(name);if(dataset.equals("Other JSON metadata"))unknownJsonFiles++;try(Reader reader=new BufferedReader(new InputStreamReader(input.open(),StandardCharsets.UTF_8))){JsonRecords.read(reader,(group,row)->{records++;bump(datasets,dataset);boolean chat=(row.has("From")||row.has("Sender")||row.has("Username"))&&(row.has("Created")||row.has("Date")||row.has("Timestamp"))&&(row.has("Content")||row.has("Text")||row.has("Media Type")||category(name).equals("Chats"));if(chat)chatRecords++;boolean sticker=dataset.equals("Stickers and custom stickers")||key(group).contains("sticker");references(row,sticker,chat,0);});}catch(Exception|OutOfMemoryError ignored){metadataIssues++;}}
  else if(extension.equals("html")&&leaf(name).toLowerCase(Locale.ROOT).startsWith("subpage_")){htmlFiles++;try(Reader reader=new BufferedReader(new InputStreamReader(input.open(),StandardCharsets.UTF_8));StreamParser parser=new StreamParser(Parser.htmlParser()).parse(reader,"")){Element node;while((node=parser.selectNext(".rightpanel > div"))!=null){if(node.selectFirst("h4")!=null&&node.selectFirst("h6")!=null){htmlMessages++;for(Element media:node.select("img[src],video[src],audio[src],source[src],a[href]")){String value=media.hasAttr("src")?media.attr("src"):media.attr("href");if(!media.tagName().equals("a")||MEDIA_EXT.contains(ext(value)))ref(value,false,true);}}node.remove();}}catch(Exception|OutOfMemoryError ignored){metadataIssues++;}}
 }
 JSONObject report(){JSONObject out=new JSONObject();out.put("tool","Offline Snap Export Inspector v1");out.put("scope","Counts only. This is an inventory and candidate-reference check, not proof that every file belongs to a chat.");out.put("input_files",files);out.put("declared_input_bytes",bytes);out.put("media_files",assetId);out.put("asset_categories",new JSONObject(assets));out.put("unrecognized_asset_format_files",unrecognizedAssetFormats);out.put("formats",new JSONObject(formats));out.put("json_files",jsonFiles);out.put("html_chat_pages",htmlFiles);out.put("json_object_records_observed",records);out.put("json_chat_records_observed",chatRecords);out.put("html_chat_entries_observed",htmlMessages);out.put("dataset_record_categories",new JSONObject(datasets));out.put("reference_counts",new JSONObject(refStats));out.put("unknown_json_files",unknownJsonFiles);out.put("metadata_files_partially_read_or_unsupported",metadataIssues);out.put("nested_archive_passes",nestedArchives);out.put("limitations",new JSONArray(Arrays.asList("No downloads are performed. URLs are not media files and some may be ordinary metadata links.","Ambiguous file names/IDs are not automatically assigned.","Byte-identical duplicate files are not hashed or deduplicated during inventory.","Filename classification is provisional; original files and values are never changed.","Unknown JSON is counted and inspected for known reference fields, not discarded.","Animation candidates retain original formats; this tool does not certify device codec support.","No filenames, paths, message contents, names, media IDs, or media bytes appear in this report.")));return out;}
 static String escape(String text){return text.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String table(JSONObject values){StringBuilder out=new StringBuilder("<table><tbody>");List<String> names=new ArrayList<>();Iterator<String> keys=values.keys();while(keys.hasNext())names.add(keys.next());Collections.sort(names);for(String name:names)out.append("<tr><td>").append(escape(name)).append("</td><td class=num>").append(values.optLong(name)).append("</td></tr>");return out.append("</tbody></table>").toString();}
 static String html(JSONObject report){
  StringBuilder page=new StringBuilder("<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><meta http-equiv=Content-Security-Policy content=\"default-src 'none'; style-src 'unsafe-inline'\"><title>Local export inventory</title><style>body{font:16px system-ui;max-width:900px;margin:36px auto;padding:20px;background:#10191d;color:#eaf0f3}h1{font-size:32px;color:#70d6bf}h2{margin-top:36px}p{line-height:1.6;color:#b7c7ce}.cards{display:flex;gap:12px;flex-wrap:wrap}.card{background:#1e2a30;border-radius:12px;padding:20px;min-width:150px;flex:1}.big{display:block;font-size:30px;font-weight:700;color:#70d6bf}table{width:100%;border-collapse:collapse;background:#1e2a30}td{padding:12px;border-bottom:1px solid #34434b}.num{text-align:right;font-variant-numeric:tabular-nums}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#1e2a30;padding:20px}summary{cursor:pointer;padding:18px 0}.note{border-left:3px solid #70d6bf;padding-left:16px}</style><p>LOCAL REPORT · NO AUTOMATIC SHARING</p><h1>What’s in your Snapchat export</h1><p>This inventory covers the whole selected export, including custom stickers. Keep the report on your Mac unless you choose to share it.</p><div class=cards>");
  page.append("<div class=card><span class=big>").append(report.optLong("media_files")).append("</span>Media and asset files</div><div class=card><span class=big>").append(report.optLong("json_files")).append("</span>JSON data files</div><div class=card><span class=big>").append(report.optLong("html_chat_pages")).append("</span>HTML chat pages</div></div><h2>Media, stickers and attachments</h2>").append(table(report.getJSONObject("asset_categories")));
  if(report.optLong("unrecognized_asset_format_files")>0)page.append("<p class=note>").append(report.optLong("unrecognized_asset_format_files")).append(" asset files have an unrecognized format. They were counted, not discarded or changed.</p>");
  page.append("<h2>Available JSON data</h2><p>Records observed by category. These are inventory counts, not unique-message totals; exports can repeat the same events across formats.</p>").append(table(report.getJSONObject("dataset_record_categories"))).append("<h2>Media references</h2><p>Matches below are filename or ID candidates. They do not by themselves prove a chat association or confirm that a phone can play the file. Remote-only links are not downloaded.</p>").append(table(report.getJSONObject("reference_counts")));
  if(report.optLong("metadata_files_partially_read_or_unsupported")>0)page.append("<p class=note>").append(report.optLong("metadata_files_partially_read_or_unsupported")).append(" metadata files could not be fully inspected. This is a partial inventory. Your originals remain unchanged.</p>");
  page.append("<h2>What this enables</h2><p>Use this inventory to see which local files, custom stickers, metadata and references can inform the next Android import update. Unsupported data is identified for follow-up; this tool does not change the Android app.</p><p>No names, messages, source paths, media IDs, URLs or media contents are included in this report.</p><details><summary>Formats and additional counts</summary>").append(table(report.getJSONObject("formats"))).append("<pre>").append(escape(report.toString(2))).append("</pre></details>");return page.toString();
 }
 static Path root(){return Paths.get(System.getProperty("user.home"),"Library","Application Support","Snap Export Inspector");}
 static void deleteReports()throws Exception{
  Path root=root();if(!Files.exists(root))return;
  if(Files.isSymbolicLink(root)||!Files.isRegularFile(root.resolve("inspector-owned.marker"),LinkOption.NOFOLLOW_LINKS)||!new String(Files.readAllBytes(root.resolve("inspector-owned.marker")),StandardCharsets.UTF_8).equals(MARKER))throw new IOException("Unrecognized report directory");
  try(DirectoryStream<Path> children=Files.newDirectoryStream(root)){for(Path run:children){if(!run.getFileName().toString().matches("report-[0-9a-f-]{36}")||Files.isSymbolicLink(run)||!Files.isDirectory(run,LinkOption.NOFOLLOW_LINKS))continue;Path owned=run.resolve("run-owned.marker");if(!Files.isRegularFile(owned,LinkOption.NOFOLLOW_LINKS)||!new String(Files.readAllBytes(owned),StandardCharsets.UTF_8).equals(MARKER))continue;for(String name:Arrays.asList("summary.json","report.html","run-owned.marker"))Files.deleteIfExists(run.resolve(name));try{Files.delete(run);}catch(DirectoryNotEmptyException keepUserFiles){}}}
  Files.deleteIfExists(root.resolve("latest-report.txt"));Files.deleteIfExists(root.resolve("inspector-owned.marker"));try{Files.delete(root);}catch(DirectoryNotEmptyException keepUserFiles){}
 }
 public static void main(String[] args){Thread.setDefaultUncaughtExceptionHandler((t,e)->System.err.println("Inspection stopped. Private error details were not printed."));try{if(args.length==1&&args[0].equals("--deletepersonal")){deleteReports();System.out.println("Local inspector reports deleted. Original exports were not changed.");return;}if(args.length==0)throw new IOException("No inputs");OfflineInspector checker=new OfflineInspector();for(String name:args)checker.inputs.add(Paths.get(name).toAbsolutePath());System.out.println("Indexing local files. No downloads or uploads are performed.");for(Path input:checker.inputs)checker.entries(input,checker::index,0);System.out.println("Checking JSON, HTML and media references locally.");for(Path input:checker.inputs)checker.entries(input,checker::inspect,0);Path root=root();if(Files.isSymbolicLink(root))throw new IOException("Unsafe report directory");Files.createDirectories(root);Path marker=root.resolve("inspector-owned.marker");if(Files.exists(marker)&&!new String(Files.readAllBytes(marker),StandardCharsets.UTF_8).equals(MARKER))throw new IOException("Unrecognized report directory");Files.write(marker,MARKER.getBytes(StandardCharsets.UTF_8));Path run=root.resolve("report-"+UUID.randomUUID());Files.createDirectory(run);Files.write(run.resolve("run-owned.marker"),MARKER.getBytes(StandardCharsets.UTF_8));JSONObject report=checker.report();Files.write(run.resolve("summary.json"),report.toString(2).getBytes(StandardCharsets.UTF_8));Files.write(run.resolve("report.html"),html(report).getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("latest-report.txt"),run.resolve("report.html").toString().getBytes(StandardCharsets.UTF_8));System.out.println("Inspection finished. Reports remain in your local inspector report folder.");}catch(Exception|OutOfMemoryError error){System.err.println("Inspection could not finish. No private error details were printed; original exports were not changed.");System.exit(1);}}
}
